CREATE TABLE IF NOT EXISTS runs ( run_id TEXT PRIMARY KEY, pilot TEXT NOT NULL, difficulty TEXT NOT NULL, round INTEGER NOT NULL, score INTEGER NOT NULL, air_kills INTEGER NOT NULL, ground_kills INTEGER NOT NULL, earned INTEGER NOT NULL, spent INTEGER NOT NULL, time_s INTEGER NOT NULL, ended TEXT NOT NULL, mod_version TEXT NOT NULL, submitted INTEGER NOT NULL, ip_hash TEXT NOT NULL );
CREATE INDEX IF NOT EXISTS runs_round ON runs (difficulty, round DESC, score DESC);
CREATE INDEX IF NOT EXISTS runs_score ON runs (difficulty, score DESC);
CREATE INDEX IF NOT EXISTS runs_pilot ON runs (pilot);
CREATE INDEX IF NOT EXISTS runs_ip ON runs (ip_hash, submitted);
CREATE TABLE IF NOT EXISTS specials ( run_id TEXT NOT NULL, kind TEXT NOT NULL, round INTEGER NOT NULL, seconds INTEGER NOT NULL, won INTEGER NOT NULL, pilot TEXT NOT NULL, difficulty TEXT NOT NULL );
CREATE INDEX IF NOT EXISTS specials_fast ON specials (kind, won, seconds);
CREATE TABLE IF NOT EXISTS settings ( key TEXT PRIMARY KEY, value TEXT NOT NULL );
CREATE TABLE IF NOT EXISTS builds ( mod TEXT NOT NULL, build TEXT NOT NULL, note TEXT, added INTEGER NOT NULL, PRIMARY KEY (mod, build) );
CREATE TABLE IF NOT EXISTS builds_seen ( mod TEXT NOT NULL, build TEXT NOT NULL, first INTEGER NOT NULL, last INTEGER NOT NULL, n INTEGER NOT NULL, pilot TEXT, PRIMARY KEY (mod, build) );
CREATE TABLE IF NOT EXISTS resets ( reset_id TEXT PRIMARY KEY, at INTEGER NOT NULL, runs INTEGER NOT NULL, specials INTEGER NOT NULL, restored INTEGER );
CREATE TABLE IF NOT EXISTS runs_archive ( reset_id TEXT NOT NULL, reset_at INTEGER NOT NULL, run_id TEXT NOT NULL, pilot TEXT, difficulty TEXT, round INTEGER, score INTEGER, air_kills INTEGER, ground_kills INTEGER, earned INTEGER, spent INTEGER, time_s INTEGER, ended TEXT, mod_version TEXT, submitted INTEGER, ip_hash TEXT, aircraft TEXT, how TEXT, tier TEXT, aces INTEGER, allies INTEGER, af_down INTEGER, captured INTEGER, build TEXT, verified INTEGER );
CREATE INDEX IF NOT EXISTS runs_archive_reset ON runs_archive (reset_id);
CREATE INDEX IF NOT EXISTS runs_archive_run ON runs_archive (run_id);
CREATE TABLE IF NOT EXISTS specials_archive ( reset_id TEXT NOT NULL, reset_at INTEGER NOT NULL, run_id TEXT NOT NULL, kind TEXT, round INTEGER, seconds INTEGER, won INTEGER, pilot TEXT, difficulty TEXT );
CREATE INDEX IF NOT EXISTS specials_archive_reset ON specials_archive (reset_id);
CREATE TABLE IF NOT EXISTS admin_fails ( ip_hash TEXT NOT NULL, at INTEGER NOT NULL );
CREATE INDEX IF NOT EXISTS admin_fails_ip ON admin_fails (ip_hash, at);
